.crumb{font-size:13px;letter-spacing:.05em;color:#8b8276;margin:0 0 12px}
h1{font-size:25px;line-height:1.4;margin:0 0 12px}
.lede{margin:0 0 22px;color:#3d3831}
.panel{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:18px 16px 20px}
.ctl{display:flex;flex-direction:column;gap:14px;margin:0 0 18px}
.row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.row label{font-size:15px;color:#4a453d;min-width:120px}
.row input[type=range]{flex:1 1 160px;min-width:120px;height:36px;accent-color:var(--accent)}
.row output{font-variant-numeric:tabular-nums;font-weight:600;min-width:2.5em;text-align:right}
.presets{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 16px}
.btn{min-height:44px;min-width:44px;padding:0 14px;border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--ink);font:inherit;font-size:15px;cursor:pointer}
.btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.btn[aria-pressed=true]{border-color:var(--accent);background:#fdf1e9;color:#7d3a12}
.segbar{display:flex;gap:4px;margin:0 0 6px;font-size:13px;color:#58524a}
.seg{padding:3px 8px;border-radius:7px;white-space:nowrap;overflow:hidden}
.seg-old{background:#e8edf5;color:#33507a}
.seg-new{background:#e6f2ea;color:#2c6a46}
#grid{display:grid;gap:3px;justify-items:stretch}
.rl{font-size:11px;color:#8b8276;display:flex;align-items:center}
.cell{aspect-ratio:1/1;border-radius:3px;background:var(--mask)}
.cell.old{background:var(--old)}
.cell.new{background:var(--new)}
.axis{font-size:13px;color:#7d7568;margin:8px 0 0}
.read{margin:16px 0 0;border-top:1px dashed var(--line);padding-top:14px}
.read dl{margin:0;display:grid;grid-template-columns:1fr auto;gap:8px 12px;font-size:16px}
.read dt{color:#4a453d}
