<script>
(function(){
function cnt(v){return v.toLocaleString('en-US');}
function bytes(v){var mib=v/1048576;return mib>=1?(mib<10?mib.toFixed(1):Math.round(mib))+' MiB':Math.round(v/1024)+' KiB';}
function flop(v){
  if(v>=1e12)return (v/1e12).toFixed(1)+' TFLOPs';
  if(v>=1e9)return (v/1e9).toFixed(1)+' GFLOPs';
  if(v>=1e6)return (v/1e6).toFixed(1)+' MFLOPs';
  if(v>=1e3)return (v/1e3).toFixed(0)+' KFLOPs';
  return v+' FLOPs';
}

/* ---------- 第二屏：依赖图 ---------- */
var depMode='rnn';
var xs=[62,132,202,272], ys=[46,112,178];
function drawDep(){
  var mode=depMode;
  var s='<svg viewBox="0 0 336 240" width="100%" role="img" aria-label="'+(mode==='rnn'?'三层 RNN 的依赖':'三层因果 Transformer 的依赖')+'">';
  s+='<defs><marker id="arw" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="#8a8175"></path></marker>';
  s+='<marker id="arh" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="#b4531f"></path></marker></defs>';
  var l,i;
  for(l=0;l<2;l++){for(i=0;i<4;i++){
    s+='<line x1="'+xs[i]+'" y1="'+(ys[l]+13)+'" x2="'+xs[i]+'" y2="'+(ys[l+1]-15)+'" stroke="#8a8175" stroke-width="1.6" marker-end="url(#arw)"></line>';
  }}
  if(mode==='rnn'){
    for(l=0;l<3;l++){for(i=0;i<3;i++){
      s+='<line x1="'+(xs[i]+13)+'" y1="'+ys[l]+'" x2="'+(xs[i+1]-15)+'" y2="'+ys[l]+'" stroke="#b4531f" stroke-width="1.8" marker-end="url(#arh)"></line>';
    }}
  }else{
    for(l=1;l<3;l++){for(i=1;i<4;i++){
      s+='<line x1="'+xs[i-1]+'" y1="'+(ys[l-1]+9)+'" x2="'+(xs[i]-9)+'" y2="'+(ys[l]-9)+'" stroke="#b4531f" stroke-width="1.4" stroke-dasharray="4 3" marker-end="url(#arh)"></line>';
    }}
  }
  for(l=0;l<3;l++){for(i=0;i<4;i++){
    s+='<circle cx="'+xs[i]+'" cy="'+ys[l]+'" r="10" fill="#f4efe5" stroke="#b8ac9a" stroke-width="1.4"></circle>';
  }}
  s+='<text x="4" y="51" font-size="11" fill="#8a8175">层 1</text>';
  s+='<text x="4" y="117" font-size="11" fill="#8a8175">层 2</text>';
  s+='<text x="4" y="183" font-size="11" fill="#8a8175">层 3</text>';
  for(i=0;i<4;i++){
    s+='<text x="'+xs[i]+'" y="214" font-size="11" fill="#8a8175" text-anchor="middle">位置 '+(i+1)+'</text>';
  }
  s+='<text x="4" y="232" font-size="11" fill="#8a8175">灰箭头：跨层依赖　橙箭头：本图多出来的等待</text>';
  s+='</svg>';
  document.getElementById('dFig').innerHTML=s;
  document.getElementById('dChain').textContent=(mode==='rnn')?'12':'3';
  document.getElementById('dPar').textContent=(mode==='rnn')?'不能':'能';
  document.getElementById('dCap').textContent=(mode==='rnn')
    ?'橙色横箭头就是同层等待：第 t 个位置要等第 t−1 个位置交出状态。三层都要走完这条横链。'
    :'同一层里没有横箭头：上一层交出结果，这一层的四个已知 token 就能同时开始。橙色虚线表示一个查询在这一层还能读到左边更早的位置。';
  document.getElementById('dRnn').className=(mode==='rnn')?'on':'';
  document.getElementById('dTr').className=(mode==='tr')?'on':'';
}
document.getElementById('dRnn').addEventListener('click',function(){depMode='rnn';drawDep();});
document.getElementById('dTr').addEventListener('click',function(){depMode='tr';drawDep();});
drawDep();

/* ---------- 第三屏：投影节点 ---------- */
var K3=4096, n3=1024;
function render3(){
  var m=parseInt(document.getElementById('m3').value,10);
  document.getElementById('m3v').textContent=m;
  var NW=K3*n3, F=2*m*K3*n3, by=NW*2;
  document.getElementById('rW').textContent=cnt(NW);
  document.getElementById('rF').textContent=flop(F);
  document.getElementById('rB').textContent=bytes(by);
  var btns=[['n3a',1024],['n3b',4096],['n3c',12288]];
  btns.forEach(function(p){document.getElementById(p[0]).className=(p[1]===n3)?'on':'';});
}
document.getElementById('m3').addEventListener('input',render3);
[['n3a',1024],['n3b',4096],['n3c',12288]].forEach(function(p){
  document.getElementById(p[0]).addEventListener('click',function(){n3=p[1];render3();});
});
render3();

/* ---------- 第四屏：配对数 ---------- */
function val(id){return parseInt(document.getElementById(id).value,10);}
function render4(){
  var S=val('s4'),P=val('p4'),B=val('b4');
  document.getElementById('s4v').textContent=S;
  document.getElementById('p4v').textContent=P;
  document.getElementById('b4v').textContent=B;
  var cols=S+P, grid=document.getElementById('grid');
  grid.style.setProperty('--cols',cols);
  var html='',i,c;
  for(i=1;i<=P;i++){
    html+='<div class="rl">q'+i+'</div>';
    for(c=0;c<cols;c++){
      var cls='cell ';
      if(c<S){cls+='old';}
      else{var k=c-S+1;cls+=(k<=i)?'new':'mask';}
      html+='<div class="'+cls+'"></div>';
    }
  }
  grid.innerHTML=html;
  var segOld=document.getElementById('segOld');
  segOld.style.display=S?'block':'none';
  segOld.style.flex=S+' 1 0';
  segOld.textContent='旧上下文 '+S;
  var segNew=document.getElementById('segNew');
  segNew.style.flex=P+' 1 0';
  segNew.textContent='本次新输入 '+P;
  var m=B*P, nd=B*P*S, nt=B*P*(P+1)/2, N=nd+nt;
  document.getElementById('m4').textContent=m;
  document.getElementById('nd4').textContent=cnt(nd);
  document.getElementById('nt4').textContent=cnt(nt);
  document.getElementById('n4').textContent=cnt(N);
  document.getElementById('f4').textContent=cnt(16384*N);
  document.getElementById('pre1').className=(S===0&&P===6&&B===1)?'on':'';
  document.getElementById('pre2').className=(S===12&&P===6&&B===1)?'on':'';
}
['s4','p4','b4'].forEach(function(id){document.getElementById(id).addEventListener('input',render4);});
document.getElementById('pre1').addEventListener('click',function(){
  document.getElementById('s4').value=0;document.getElementById('p4').value=6;document.getElementById('b4').value=1;render4();});
document.getElementById('pre2').addEventListener('click',function(){
  document.getElementById('s4').value=12;document.getElementById('p4').value=6;document.getElementById('b4').value=1;render4();});
render4();

/* ---------- 第五屏：整模型 ---------- */
function totals(m,Npair,mout){
  var lin=36*385875968*m;
  var att=36*16384*Npair;
  var voc=2*mout*4096*151936;
  return {lin:lin,att:att,voc:voc,sum:lin+att+voc};
}
function render5(which){
  var shape=(which===2)
    ?{m:1,Npair:1*8192+1*(1+1)/2,mout:1}
    :{m:8192,Npair:8192*8193/2,mout:1};
  var t=totals(shape.m,shape.Npair,shape.mout);
  document.getElementById('m5').textContent=cnt(shape.m);
  document.getElementById('n5').textContent=cnt(shape.Npair);
  document.getElementById('o5').textContent=cnt(shape.mout);
  document.getElementById('lin5').textContent=flop(t.lin);
  document.getElementById('att5').textContent=flop(t.att);
  document.getElementById('voc5').textContent=flop(t.voc);
  document.getElementById('sum5').textContent=flop(t.sum);
  document.getElementById('t1').className=(which===1)?'on':'';
  document.getElementById('t2').className=(which===2)?'on':'';
}
document.getElementById('t1').addEventListener('click',function(){render5(1);});
document.getElementById('t2').addEventListener('click',function(){render5(2);});
render5(1);

/* ---------- 原文依据按钮 ---------- */
Array.prototype.forEach.call(document.querySelectorAll('.src'),function(b){
  b.addEventListener('click',function(){
    var box=document.getElementById(b.getAttribute('data-quote'));
    if(box){box.classList.toggle('on');}
  });
});
})();
</script>
